function setupCellEditing() {
    const spreadsheetBody = document.getElementById('spreadsheet-body');

    if (!spreadsheetBody) {
        console.error("Error: No se encontró el cuerpo de la hoja de cálculo con id 'spreadsheet-body'.");
        return;
    }

    /**
     * Función auxiliar para obtener el valor numérico de una celda dada su referencia (ej: "A1").
     * @param {string} reference - La referencia de la celda.
     * @returns {number|null} El valor numérico o null si no se encuentra/es inválido.
     */
    function getCellValue(reference) {
        // Ejemplo de regex para capturar columna y fila (A1, B2, etc.)
        const match = reference.match(/([A-Z]+)([0-9]+)/i);
        if (!match) return null;

        const colChar = match[1].toUpperCase();
        const rowNum = parseInt(match[2]);

        // Convertir letra de columna a índice (A=0, B=1, ...)
        let colIndex = 0;
        for (let i = 0; i < colChar.length; i++) {
            colIndex += Math.pow(26, colChar.length - 1 - i) * (colChar.charCodeAt(i) - 'A'.charCodeAt(0) + 1 - 1);
        }

        // Buscar la celda en el DOM usando los atributos data-col y data-row
        const targetCell = spreadsheetBody.querySelector(`[data-col="${colIndex - 1}"][data-row="${rowNum - 1}"]`);

        if (targetCell && targetCell.textContent) {
            // Intentar parsear el contenido como número, ignorando fórmulas si ya se calcularon
            const value = targetCell.textContent.trim();
            if (!isNaN(parseFloat(value)) && isFinite(value)) {
                return parseFloat(value);
            }
        }
        return null;
    }

    /**
     * Función simple para evaluar fórmulas básicas (SUMA de rango).
     * Nota: Esta implementación es muy básica y solo maneja el caso SUMA(A1:A3)
     * @param {HTMLElement} target - La celda donde se ingresó la fórmula.
     * @param {string} formulaString - El texto completo de la fórmula (ej: "=SUMA(A1:A3)").
     * @returns {number|string} El resultado calculado o el string original si falla.
     */
    function evaluateFormula(formulaString) {
        // 1. Limpiar y extraer contenido entre paréntesis, asumiendo formato SUMA(...)
        const sumMatch = formulaString.match(/SUMA\(([^)]+)\)/i);
        if (!sumMatch || !sumMatch[1]) return formulaString;

        const rangeString = sumMatch[1]; // Ej: A1:A3 o B2;C3
        let valuesToSum = [];

        // Manejar rangos (ej: A1:A3) y celdas sueltas separadas por ; (ej: A1;B2)
        const parts = rangeString.split(':').map(part => part.trim());

        for (const part of parts) {
            if (!part) continue;

            // Si es un rango (A1:A3), necesitamos iterar sobre las celdas
            const rangeMatch = part.match(/([A-Z]+)([0-9]+):([A-Z]+)([0-9]+)/i);
            if (rangeMatch) {
                const startColChar = rangeMatch[1].toUpperCase();
                const endColChar = rangeMatch[3].toUpperCase();
                const startRow = parseInt(rangeMatch[2]);
                const endRow = parseInt(rangeMatch[4]);

                // Iterar sobre columnas y filas del rango
                for (let r = startRow; r <= endRow; r++) {
                    for (let cChar = startColChar; cChar <= endColChar; cChar++) {
                        // Esto es una simplificación extrema, asumiendo que las letras son secuenciales.
                        // Para un entorno real se usaría lógica de conversión A->1, B->2...
                        // Aquí solo nos enfocamos en el caso simple A1:A3 donde la columna no cambia.
                        if (cChar === startColChar) {
                             valuesToSum.push(getCellValue(`${startColChar}${r}`));
                        }
                    }
                }
            } else if (part.includes(';')) {
                 // Manejar celdas sueltas separadas por ; si el rango no se detectó correctamente
                 const individualCells = part.split(';').map(s => s.trim());
                 individualCells.forEach(cellRef => {
                     valuesToSum.push(getCellValue(cellRef));
                 });
            } else {
                // Celda única (ej: A1)
                valuesToSum.push(getCellValue(part));
            }
        }

        // Filtrar valores nulos y sumar los números válidos
        const validNumbers = valuesToSum.filter(v => v !== null && !isNaN(v)).map(Number);
        if (validNumbers.length === 0) return "Error";

        const sum = validNumbers.reduce((acc, val) => acc + val, 0);
        return sum;
    }


    // Usamos event delegation para escuchar cambios en cualquier <td> dentro del tbody.
    spreadsheetBody.addEventListener('input', function(event) {
        const target = event.target;

        // Verificamos si el elemento que disparó el evento es una celda de datos editable.
        if (target.tagName === 'TD' && target.hasAttribute('contenteditable')) {
            const col = target.getAttribute('data-col');
            const row = target.getAttribute('data-row');
            let value = target.textContent;

            // 1. DETECTAR FÓRMULA Y CALCULAR
            if (value.trim().startsWith('=')) {
                try {
                    const calculatedValue = evaluateFormula(value);

                    // Actualizar el contenido de la celda para mostrar el resultado numérico/texto calculado
                    target.textContent = calculatedValue; 
                    value = String(calculatedValue); // Usamos el valor calculado para el log

                    console.log(`Celda ${col}${row} (Fórmula) calculada: "${value}"`);
                } catch (e) {
                    // Si falla la evaluación, dejamos que se muestre la fórmula original y logueamos el error.
                    console.error("Error al evaluar la fórmula:", e);
                    // No hacemos nada con target.textContent para mantener la fórmula visible.
                }
            } else {
                // 2. LÓGICA NORMAL DE INPUT (No es una fórmula)
                const newValue = value;
                console.log(`Celda ${col}${row} actualizada: "${newValue}"`);
            }
        }
    });

    // Opcional: Manejar el evento de foco para asegurar que la experiencia sea fluida al hacer clic.
    spreadsheetBody.addEventListener('focusin', function(event) {
        const target = event.target;
        if (target.tagName === 'TD' && target.hasAttribute('contenteditable')) {
            // Esto simplemente asegura que el foco está en la celda correcta, lo cual es nativo, 
            // pero ayuda a confirmar la funcionalidad de edición.
            console.log(`Foco puesto en ${target.getAttribute('data-col')}${target.getAttribute('data-row')}. Listo para editar.`);
        }
    });
}
