### FUNCION: calculateFormula
```javascript
/**
 * Evalúa una fórmula de hoja de cálculo dada su cadena y la celda objetivo.
 * @param {string} formulaString La fórmula a evaluar (ej: "=SUMA(A1:A3)").
 * @param {HTMLElement} targetElement El elemento TD donde se ingresó la fórmula.
 * @returns {string|null} El resultado calculado como string, o null si falla.
 */
function calculateFormula(formulaString, targetElement) {
    let formula = formulaString.trim();

    if (!formula || !formula.startsWith('=')) {
        return null; // No es una fórmula
    }

    // 1. Limpiar la fórmula: quitar el '=' inicial y reemplazar nombres de funciones en mayúsculas.
    formula = formula.substring(1).toUpperCase().trim();

    try {
        let result = null;

        // --- Manejo de SUMA (Rango o Celdas Sueltas) ---
        if (formula.startsWith('SUMA')) {
            const content = formula.substring(4).trim(); // Quitar "SUMA"
            let valuesToSum = [];

            if (!content) return null;

            // Detectar si es un rango (ej: A1:A3)
            const rangeMatch = content.match(/^([A-Z]+)\s*:\s*(\d+)$/);
            if (rangeMatch) {
                const col = rangeMatch[1];
                const startRow = parseInt(rangeMatch[2]);
                // Asumimos que el rango es vertical y empieza en la fila 1 hasta la actual.
                // Para simplificar, solo sumaremos las celdas visibles del rango A1:A3 (o lo que se defina).
                // Aquí asumiremos un rango simple de columna fija por filas consecutivas.
                for (let r = startRow; r <= 20; r++) { // Iteramos hasta la fila máxima definida en el HTML
                    const value = getCellValue(col, r);
                    if (value !== null && !isNaN(parseFloat(value))) {
                        valuesToSum.push(parseFloat(value));
                    }
                }
            } else {
                // Detectar celdas sueltas separadas por ; o ,
                const cells = content.split(/[,;]/).map(s => s.trim());
                for (const cellRef of cells) {
                    if (!cellRef) continue;

                    // Extraer coordenadas de la referencia celular (ej: A1, B2)
                    const colMatch = cellRef.match(/^([A-Z]+)/);
                    const rowMatch = cellRef.match(/(\d+)$/);

                    if (colMatch && rowMatch) {
                        const col = colMatch[1];
                        const row = parseInt(rowMatch[1]);
                        const value = getCellValue(col, row);
                        if (value !== null && !isNaN(parseFloat(value))) {
                            valuesToSum.push(parseFloat(value));
                        }
                    }
                }
            }

            result = valuesToSum.reduce((acc, val) => acc + val, 0);
        } else {
            // --- Manejo de Operadores Aritméticos (A1-B1, A1*B1, etc.) ---
            // Usamos eval() con precaución, pero es el método más directo para evaluar expresiones matemáticas complejas.
            let expression = formula;

            // Reemplazar referencias de celda (ej: A1) por sus valores numéricos reales.
            // Esto requiere encontrar patrones como [A-Z]+\d+ y reemplazarlos en la expresión.
            expression = expression.replace(/([A-Z]+)(\d+)/g, (match, col, rowStr) => {
                const row = parseInt(rowStr);
                const value = getCellValue(col, row);
                return isNaN(parseFloat(value)) ? '0' : parseFloat(value).toString(); // Usar 0 si no se encuentra o es inválido
            });

            // Evaluar la expresión matemática resultante.
            if (expression) {
                 result = eval(expression);
            } else {
                return null;
            }
        }


        if (result === undefined || result === null) return null;
        return parseFloat(result).toString();

    } catch (e) {
        console.error("Error al procesar la fórmula:", e);
        return null; // Devolver null si hay un error de cálculo
    }
}
