### FUNCION: recalculateDependencies
```javascript
/**
 * Intenta recalcular el valor de una celda y todas las celdas que dependen de ella.
 * @param {HTMLElement} changedCell - La celda que ha sido modificada (el evento 'input').
 */
function recalculateDependencies(changedCell) {
    const col = changedCell.getAttribute('data-col');
    const row = changedCell.getAttribute('data-row');

    // 1. Intentar recalcular la propia celda si contiene una fórmula.
    if (changedCell.dataset.isFormula === 'true') {
        try {
            const formulaValue = evaluateFormula(changedCell);
            changedCell.textContent = formulaValue;
            console.log(`Recálculo exitoso para ${col}${row}: ${formulaValue}`);
        } catch (e) {
            console.error(`Error al recalcular la fórmula en ${col}${row}:`, e);
        }
    }

    // 2. Iterar sobre todas las celdas y verificar si dependen de la celda cambiada.
    const allCells = document.querySelectorAll('#spreadsheet-body td[contenteditable="true"]');
    let recalculatedCount = 0;

    allCells.forEach(cell => {
        // Solo necesitamos recalcular si la celda es una fórmula y no es la que acaba de cambiar (ya lo hicimos arriba).
        if (cell !== changedCell && cell.dataset.isFormula === 'true') {
            const formula = cell.textContent;
            // Simple chequeo: ¿contiene la fórmula la referencia a la columna/fila cambiada?
            if (formula.includes(`${col}${row}`)) {
                try {
                    const newValue = evaluateFormula(cell);
                    if (newValue !== cell.textContent) {
                        cell.textContent = newValue;
                        console.log(`Recálculo de dependencia exitoso en ${cell.getAttribute('data-col')}${cell.getAttribute('data-row')}: ${newValue}`);
                        recalculatedCount++;
                    }
                } catch (e) {
                    // Ignorar errores si la fórmula no puede ser evaluada por alguna razón.
                }
            }
        }
    });

    if (recalculatedCount > 0) {
        console.log(`Recálculo de dependencias completado. ${recalculatedCount} celdas actualizadas.`);
    }
}
