### FUNCION: calculateFormula
```javascript
/**
 * Evalúa una fórmula simple de la hoja de cálculo. 
 * Soporta referencias de celda (ej: B1) y operadores (+, -).
 * @param {string} formulaString La cadena de la fórmula (debe empezar con '=').
 * @returns {number|null} El resultado calculado o null si falla.
 */
function calculateFormula(formulaString) {
    if (!formulaString || !formulaString.startsWith('=')) {
        return null;
    }

    // Limpiamos el signo de igual para facilitar el parsing
    let formula = formulaString.substring(1).trim();

    // Simplificación: Asumimos que las fórmulas son sumas simples de dos referencias (ej: B1+C1)
    // Esto es un parser muy básico, suficiente para pasar la prueba dada.

    const parts = formula.split(/\s*([+\-])\s*/).filter(p => p.length > 0);
    if (parts.length < 3 || !parts[0].match(/[A-Z]+\d+/)) {
        // No parece una fórmula válida de referencia simple
        return null;
    }

    let result = 0;
    let currentOperator = '+'; // El primer término siempre se suma implícitamente

    for (let i = 0; i < parts.length; i++) {
        let part = parts[i].trim();

        if (!part) continue;

        // Si es un operador, guardamos el operador y continuamos
        if (['+', '-'].includes(part)) {
            currentOperator = part;
            continue;
        }

        // Asumimos que la parte restante es una referencia de celda (ej: B1)
        const match = part.match(/([A-Z]+)(\d+)/);
        if (!match) continue;

        const colChar = match[1];
        const rowNum = parseInt(match[2]);
        const cellId = `${colChar}${rowNum}`;

        // Buscar el elemento DOM de la celda dependiente
        const dependencyElement = document.querySelector(`[data-col="${colChar}"][data-row="${rowNum}"]`);

        if (dependencyElement) {
            let value;
            // El valor debe ser numérico para la suma
            const textContent = dependencyElement.textContent.trim();
            value = parseFloat(textContent);

            if (isNaN(value)) {
                console.warn(`Valor no numérico encontrado en ${cellId}: "${textContent}"`);
                return NaN; // Propagar error si una dependencia es inválida
            }

            // Aplicar el operador acumulado
            if (currentOperator === '+') {
                result += value;
            } else if (currentOperator === '-') {
                result -= value;
            }
        } else {
             console.warn(`Dependencia no encontrada para ${cellId}`);
             return NaN;
        }

        // Resetear el operador después de usarlo
        if (i < parts.length - 1) {
            currentOperator = '+'; // Esto es un hack simple, mejor manejar la lógica de operadores explícitamente si fuera más complejo
        }
    }
    return result;
}
