### FUNCION: setupColumnSelectionAndDeletion
```javascript
function setupColumnSelectionAndDeletion() {
    const spreadsheetGrid = document.getElementById('spreadsheet-grid');
    const deleteButton = document.getElementById('delete-column-btn');
    let selectedColumns = new Set();

    // 1. Manejar la selección de columnas al hacer clic en el encabezado (<th>)
    spreadsheetGrid.addEventListener('click', function(event) {
        const target = event.target;

        if (target.classList.contains('col-header')) {
            const colName = target.getAttribute('data-col');

            // Toggle selection state
            if (selectedColumns.has(colName)) {
                selectedColumns.delete(colName);
                target.style.backgroundColor = ''; // Deseleccionar visualmente
            } else {
                selectedColumns.add(colName);
                target.style.backgroundColor = '#cfe2f3'; // Seleccionar visualmente (azul claro)
            }

            // Actualizar el estado del botón de borrado
            updateDeleteButtonState();
        }
    });

    // 2. Manejar el clic en el botón "Borrar Columna(s)"
    if (deleteButton) {
        deleteButton.addEventListener('click', deleteSelectedColumns);
    }

    // Función auxiliar para actualizar la visibilidad del botón de borrado
    function updateDeleteButtonState() {
        const deleteButton = document.getElementById('delete-column-btn');
        if (deleteButton && selectedColumns.size > 0) {
            deleteButton.disabled = false;
            deleteButton.style.opacity = '1';
        } else if (deleteButton) {
            deleteButton.disabled = true;
            deleteButton.style.opacity = '0.5';
        }
    }

    // Función principal para borrar las columnas seleccionadas
    function deleteSelectedColumns() {
        if (selectedColumns.size === 0) return;

        const columnsToDelete = Array.from(selectedColumns);

        // Confirmación simple antes de la acción destructiva
        if (!confirm(`¿Está seguro que desea borrar las columnas ${columnsToDelete.join(', ')}? Esta acción es irreversible.`)) {
            return;
        }

        // 1. Borrar los encabezados (<th>)
        const headerRow = document.querySelector('#spreadsheet-grid thead tr');
        columnsToDelete.forEach(colName => {
            const colHeader = headerRow.querySelector(`.col-header[data-col="${colName}"]`);
            if (colHeader) {
                // Eliminar el elemento del DOM
                colHeader.remove();
            }
        });

        // 2. Borrar las celdas de datos (<td>) en todas las filas
        const bodyRows = document.getElementById('spreadsheet-body').querySelectorAll('tr');
        bodyRows.forEach(row => {
            columnsToDelete.forEach(colName => {
                // Buscar la celda correspondiente en esta fila
                const cellToRemove = row.querySelector(`[data-col="${colName}"]`);
                if (cellToRemove) {
                    // Limpiar contenido y eliminar el elemento del DOM
                    cellToRemove.innerHTML = ''; // Borrar contenido visible
                    cellToRemove.removeAttribute('contenteditable'); // Deshabilitar edición
                    cellToRemove.style.backgroundColor = ''; // Resetear color
                    // Nota: No eliminamos el <td> para mantener la estructura de la tabla, solo limpiamos su contenido y funcionalidad.
                }
            });
        });

        // 3. Limpiar el estado de selección
        selectedColumns.clear();
        columnsToDelete.forEach(colName => {
            const colHeader = document.querySelector(`.col-header[data-col="${colName}"]`);
            if (colHeader) {
                colHeader.style.backgroundColor = '';
            }
        });

        updateDeleteButtonState();
    }
}
```

