### FUNCION: selectColumn
```js
function selectColumn(colLetter, e) {
    // Deseleccionar cualquier columna previamente seleccionada
    document.querySelectorAll('.column-header').forEach(th => {
        th.classList.remove('selected');
        th.style.backgroundColor = ''; // Reset background color
    });

    const targetHeader = e.currentTarget;
    targetHeader.classList.add('selected');

    // Actualizar el estado de la selección y los botones
    document.getElementById('selected-column-display').textContent = colLetter;

    const isColumnSelected = !!colLetter;

    // Habilitar/Deshabilitar controles basados en si hay columna seleccionada
    document.getElementById('delete-column-btn').disabled = !isColumnSelected;
    document.getElementById('clear-column-content-btn').disabled = !isColumnSelected;
    document.getElementById('set-column-color-btn').disabled = !isColumnSelected;

    // Opcional: Aplicar un estilo visual de selección al header
    targetHeader.style.backgroundColor = '#cceeff'; 
}
