function deleteColumn() {
    const colLetter = document.getElementById('selected-column-display').textContent;
    if (colLetter === 'Ninguna') return;

    if (!confirm(`¿Está seguro de que desea borrar la columna ${colLetter}? Esta acción es irreversible.`)) {
        return;
    }

    // 1. Eliminar el encabezado de la columna
    const headerToDelete = document.querySelector('.column-header[data-col="' + colLetter + '"]');
    if (headerToDelete) {
        headerToDelete.remove();
    }

    // 2. Iterar sobre todas las filas del tbody y eliminar el TD correspondiente
    const spreadsheetBody = document.getElementById('spreadsheet-body');
    const rows = spreadsheetBody.querySelectorAll('tr');

    rows.forEach(row => {
        const tdToDelete = row.querySelector(`[data-col="${colLetter}"]`);
        if (tdToDelete) {
            // Asegurarse de que se eliminen también los bordes si es necesario, aunque el DOM lo maneja.
            tdToDelete.remove();
        }
    });

    // 3. Resetear la selección y los controles
    selectColumn(null);
    console.log(`Columna ${colLetter} eliminada exitosamente.`);
}
