function deleteSelectedColumn() {
    const selectedDisplay = document.getElementById('selected-column-display');
    const colLetter = selectedDisplay.textContent.includes('Columna') ? selectedDisplay.textContent.split(' ')[1] : null;

    if (!colLetter) {
        alert("Por favor, seleccione una columna primero.");
        return;
    }

    if (!confirm(`¿Está seguro de que desea borrar la Columna ${colLetter}? Esta acción es irreversible.`)) {
        return;
    }

    // 1. Eliminar el encabezado de la columna (<thead>)
    const headerToRemove = Array.from(document.querySelectorAll('#spreadsheet-grid thead th')).find(th => th.textContent === colLetter);
    if (headerToRemove) {
        headerToRemove.remove();
    }

    // 2. Eliminar las celdas de datos en todas las filas (<tbody>)
    const bodyRows = document.getElementById('spreadsheet-body').querySelectorAll('tr');
    let cellsRemovedCount = 0;

    bodyRows.forEach(row => {
        // Buscar la celda específica para esta columna en la fila actual
        const cellToRemove = row.querySelector(`td[data-col="${colLetter}"]`);
        if (cellToRemove) {
            // Eliminar el contenido y luego el elemento DOM
            cellToRemove.innerHTML = ''; 
            cellToRemove.remove();
            cellsRemovedCount++;
        }
    });

    // 3. Resetear la UI y el estado
    selectColumn('Ninguna'); // Esto resetea los botones y el display
    alert(`Columna ${colLetter} eliminada exitosamente. Se limpiaron ${cellsRemovedCount} celdas.`);
}
