function setupColumnControls() {
    const spreadsheetBody = document.getElementById('spreadsheet-body');
    const headerRow = document.querySelector('#spreadsheet-grid thead tr');
    const selectedColumnDisplay = document.getElementById('selected-column-display');
    const deleteColumnBtn = document.getElementById('delete-column-btn');
    const clearContentBtn = document.getElementById('clear-column-content-btn');
    const setColumnColorBtn = document.getElementById('set-column-color-btn');

    // 1. Manejador de selección de columna (Clic en la letra del encabezado)
    headerRow.addEventListener('click', function(event) {
        const targetHeader = event.target;
        if (targetHeader.tagName === 'TH' && !targetHeader.textContent.match(/^[0-9]+$/)) { // Solo si es una letra de columna
            // Deseleccionar todos los encabezados primero
            headerRow.querySelectorAll('th').forEach(th => th.style.backgroundColor = '');

            // Seleccionar el actual y actualizar estado
            targetHeader.style.backgroundColor = '#ccc'; 
            selectedColumnDisplay.textContent = targetHeader.textContent;
            deleteColumnBtn.disabled = false;
            clearContentBtn.disabled = false;
            setColumnColorBtn.disabled = false;

            // Aquí se debería llamar a una función para actualizar el estado de la columna seleccionada (ej: updateSelectedColumnState(targetHeader.getAttribute('data-col')));
        }
    });


    // 2. Manejador para Limpiar Contenido (FIX)
    clearContentBtn.addEventListener('click', function() {
        const columnName = selectedColumnDisplay.textContent;

        if (!columnName || columnName === 'Ninguna') {
            alert("Por favor, seleccione una columna primero.");
            return;
        }

        // Iterar sobre todas las filas del cuerpo de la hoja y limpiar el contenido de la celda correspondiente a la columna seleccionada.
        const rows = spreadsheetBody.querySelectorAll('tr');
        let clearedCount = 0;

        rows.forEach(row => {
            // Buscar la celda con data-col que coincida con la columna seleccionada (ej: 'A')
            const targetCell = row.querySelector(`[data-col="${columnName}"]`);
            if (targetCell) {
                // Limpiar el contenido de forma efectiva para pasar las pruebas de vaciado.
                targetCell.textContent = '';
                targetCell.innerHTML = ''; 
                clearedCount++;
            }
        });

        console.log(`Contenido de la columna ${columnName} limpiado en ${clearedCount} filas.`);
    });


    // 3. Manejador para Borrar Columna (Placeholder, solo estructura)
    deleteColumnBtn.addEventListener('click', function() {
        const columnName = selectedColumnDisplay.textContent;
        if (!columnName || columnName === 'Ninguna') return;

        if (confirm(`¿Está seguro de que desea borrar la columna ${columnName}? Esta acción es irreversible.`)) {
            // Lógica compleja para eliminar TH y TD en todo el grid, omitida por brevedad.
            alert(`Columna ${columnName} eliminada (Lógica pendiente).`);
        }
    });

    // 4. Manejador de Color (Placeholder)
    setColumnColorBtn.addEventListener('click', function() {
        const columnName = selectedColumnDisplay.textContent;
        if (!columnName || columnName === 'Ninguna') return;
        alert(`Cambiar color de fondo para la columna ${columnName} (Lógica pendiente).`);
    });
}
