```javascript
function setupClearColumnContent() {
    const clearButton = document.getElementById('clear-column-content-btn');
    if (!clearButton) return;

    // Event listener para cuando se hace clic en el botón de limpiar contenido.
    clearButton.addEventListener('click', function() {
        // Asumimos que la columna seleccionada está visible y su letra puede extraerse del display.
        const selectedColumnDisplay = document.getElementById('selected-column-display');
        if (!selectedColumnDisplay) return;

        let colLetterText = selectedColumnDisplay.textContent.trim();

        // Si el texto es "Ninguna", no hacemos nada.
        if (colLetterText === 'Ninguna') {
            console.warn("No hay columna seleccionada para limpiar.");
            return;
        }

        // Intentamos extraer la letra de la columna del texto mostrado. 
        // Esto asume que el display solo muestra la letra o un formato simple como "A".
        const colLetter = colLetterText.toUpperCase().match(/[A-Z]/);
        if (!colLetter) {
            console.warn("No se pudo determinar la letra de la columna seleccionada.");
            return;
        }
        const selectedCol = colLetter[0];

        // Seleccionamos todas las celdas en el cuerpo que pertenecen a esta columna.
        const dataCells = document.querySelectorAll(`[data-col="${selectedCol}"]`);

        if (dataCells.length === 0) {
             console.warn(`No se encontraron celdas para la columna ${selectedCol}.`);
            return;
        }

        // Limpiamos el contenido de todas las celdas encontradas.
        dataCells.forEach(cell => {
            cell.textContent = ''; 
            cell.innerHTML = '';  
        });

        console.log(`Contenido de la columna ${selectedCol} limpiado exitosamente.`);
    });
}
