 * @param {string} col - La letra de la columna seleccionada (A-J) o 'Ninguna'.
 */
function updateColumnSelectionState(col) {
    const selectedDisplay = document.getElementById('selected-column-display');
    const deleteBtn = document.getElementById('delete-column-btn');
    const clearContentBtn = document.getElementById('clear-column-content-btn');
    const colorBtn = document.getElementById('set-column-color-btn');

