function handleRowNumberClick(event) {
    const target = event.target;
    if (!target || !target.hasAttribute('data-row')) return;

    // Obtener la fila seleccionada (el tr padre).
    const rowElement = target.closest('tr');
    if (!rowElement) return;

    // En este contexto, al hacer clic en el número de fila, asumimos que se selecciona toda la columna A.
    // Si queremos simular una selección más compleja, necesitaríamos un mecanismo global de estado.
    // Para cumplir con R7 (seleccionar y actuar sobre la columna), forzamos la selección a la primera columna visible (A).

    const selectedCol = 'A'; // Asumimos que el clic en el número de fila activa la acción sobre la Columna A por defecto, o simplemente seleccionamos la primera.
    updateColumnSelectionState(selectedCol);
}


/**
 * Inicializa los listeners para las celdas de números de fila (<th>).
 */
function setupRowNumberListeners() {
    const spreadsheetBody = document.getElementById('spreadsheet-body');
    if (!spreadsheetBody) return;

    // Delegación de eventos en el tbody para capturar clics en los <th> que contienen los números de fila.
    spreadsheetBody.addEventListener('click', function(event) {
        const target = event.target;
        // Verificamos si el objetivo es un encabezado de número de fila (el primer <th> de cada tr).
        if (target.tagName === 'TH' && !['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'].includes(target.textContent)) {
            handleRowNumberClick(event);
        }
    });
}
