```javascript
function setupRowSelectionAndClearing() {
    // Asumimos que los números de fila son elementos clickeables en la cabecera o lateral, 
    // y tienen un atributo data-row con el índice numérico.
    const rowNumberElements = document.querySelectorAll('[data-row]');
    const clearButton = document.getElementById('clear-column-content-btn');

    let activeRowIndex = null;

    // 1. Manejar la selección de fila (haciendo clic en el número)
    if (rowNumberElements.length > 0) {
        rowNumberElements.forEach(element => {
            element.addEventListener('click', function() {
                const rowIndex = parseInt(this.getAttribute('data-row'));
                activeRowIndex = rowIndex;

                // Limpiar selección visual previa y aplicar la nueva
                document.querySelectorAll('.selected-row').forEach(el => el.classList.remove('selected-row'));
                this.closest('tr') ? this.closest('tr').classList.add('selected-row') : this.classList.add('selected-row');
            });
        });
    }

    // 2. Manejar el botón de borrar contenido de la columna (borrar)
    if (clearButton) {
        clearButton.addEventListener('click', function() {
            if (activeRowIndex === null) {
                alert("Por favor, seleccione una fila primero.");
                return;
            }

            // Seleccionar todas las celdas de datos que pertenecen a la fila activa.
            // Buscamos dentro del tbody usando el atributo data-row para identificar la fila completa.
            const rowCells = document.querySelectorAll(`[data-row="${activeRowIndex}"] td`);

            if (rowCells.length === 0) {
                console.warn(`No se encontraron celdas de datos para la fila ${activeRowIndex}.`);
                return;
            }

            // Borrar contenido y resetear color de fondo en todas las celdas seleccionadas.
            rowCells.forEach(cell => {
                cell.textContent = '';
                cell.style.backgroundColor = ''; 
            });

            console.log(`Contenido de la fila ${activeRowIndex} borrado exitosamente.`);
        });
    }
}
