### FUNCION: getColumnIndexFromLetter
```javascript
function getColumnIndexFromLetter(letter) {
    if (!letter || typeof letter !== 'string') return -1;
    const charCode = letter.toUpperCase().charCodeAt(0);
    // A=65, B=66, ...
    const index = charCode - 65;
    return index;
}
```

