function setupColumnSelection() {
    const headerRow = document.querySelector('#spreadsheet-grid thead tr');
    if (!headerRow) return;

    // Event listener para seleccionar la columna al hacer clic en su encabezado (A, B, C...)
    headerRow.addEventListener('click', (e) => {
        const target = e.target;
        // Verificamos si el objetivo es un TH y contiene una letra de columna
        if (target.tagName === 'TH' && target.textContent.match(/[A-Z]/)) {
            const colLetter = target.textContent.trim();
            const columnIndex = getColumnIndexFromLetter(colLetter);

            // 1. Actualizar la visualización de la columna seleccionada
            document.getElementById('selected-column-display').textContent = colLetter;

            // 2. Habilitar controles (asumiendo que cualquier selección habilita las acciones)
            document.getElementById('delete-column-btn').disabled = false;
            document.getElementById('clear-column-content-btn').disabled = false;
            document.getElementById('set-column-color-btn').disabled = false;

            // 3. (Opcional pero bueno) Marcar visualmente la columna seleccionada, aunque no es estrictamente necesario para el bug.
        } else {
             // Si se hace clic en cualquier otro lugar del thead, deseleccionar.
             document.getElementById('selected-column-display').textContent = 'Ninguna';
             document.getElementById('delete-column-btn').disabled = true;
             document.getElementById('clear-column-content-btn').disabled = true;
             document.getElementById('set-column-color-btn').disabled = true;
        }
    });
}
