function getColumnIndexFromLetter(letter) {
    if (!letter || typeof letter !== 'string') return -1;
    const charCode = letter.toUpperCase().charCodeAt(0);
    // A=65, B=66, ...
    const index = charCode - 65;
    return index;
}

function setupColumnSelection() {
    const headerRow = document.querySelector('#spreadsheet-grid thead tr');
    if (!headerRow) return;

    // Event listener para seleccionar la columna al hacer clic en su encabezado (A, B, C...)
    headerRow.addEventListener('click', (e) => {
        const target = e.target;
        // Verificamos si el objetivo es un TH y contiene una letra de columna
        if (target.tagName === 'TH' && target.textContent.match(/[A-Z]/)) {
            const colLetter = target.textContent.trim();
            const columnIndex = getColumnIndexFromLetter(colLetter);

            // 1. Actualizar la visualización de la columna seleccionada
            document.getElementById('selected-column-display').textContent = colLetter;

            // 2. Habilitar controles (asumiendo que cualquier selección habilita las acciones)
            document.getElementById('delete-column-btn').disabled = false;
            document.getElementById('clear-column-content-btn').disabled = false;
            document.getElementById('set-column-color-btn').disabled = false;

        } else {
             // Si se hace clic en cualquier otro lugar del thead, deseleccionar.
             document.getElementById('selected-column-display').textContent = 'Ninguna';
             document.getElementById('delete-column-btn').disabled = true;
             document.getElementById('clear-column-content-btn').disabled = true;
             document.getElementById('set-column-color-btn').disabled = true;
        }
    });
}

function handleColumnAction(action) {
    const colLetter = document.getElementById('selected-column-display').textContent;
    if (colLetter === 'Ninguna') return;

    const columnIndex = getColumnIndexFromLetter(colLetter);
    if (columnIndex < 0) return;

    // Nota: El índice del TH/TD es +1 respecto al índice de la letra, debido a la primera celda vacía.
    const headerCells = document.querySelectorAll('#spreadsheet-grid thead tr th:nth-child(' + (columnIndex + 2) + ')');
    const dataCells = document.querySelectorAll('#spreadsheet-body td:nth-child(' + (columnIndex + 2) + ')');

    if (action === 'hide') {
        // Ocultar la columna
        headerCells.forEach(th => th.style.display = 'none');
        dataCells.forEach(td => td.style.display = 'none');
        console.log(`Columna ${colLetter} oculta.`);

    } else if (action === 'show') {
        // Mostrar la columna
        headerCells.forEach(th => th.style.display = ''); // Resetear display
        dataCells.forEach(td => td.style.display = '');
        console.log(`Columna ${colLetter} visible.`);
    } else if (action === 'clear') {
        // Limpiar contenido de la columna
        dataCells.forEach(td => {
            td.textContent = '';
            td.setAttribute('contenteditable', 'true'); // Asegurar que sea editable después de limpiar
        });
        console.log(`Contenido de la columna ${colLetter} limpiado.`);
    }

    // Después de la acción, deseleccionar y actualizar UI
    document.getElementById('selected-column-display').textContent = 'Ninguna';
    document.getElementById('delete-column-btn').disabled = true;
    document.getElementById('clear-column-content-btn').disabled = true;
    document.getElementById('set-column-color-btn').disabled = true;
}

function setupColumnControls() {
    const deleteBtn = document.getElementById('delete-column-btn');
    const clearBtn = document.getElementById('clear-column-content-btn');

    if (deleteBtn) {
        // Usamos delete-column-btn para ocultar/mostrar la columna (Toggle visibility)
        deleteBtn.addEventListener('click', () => {
            const colLetter = document.getElementById('selected-column-display').textContent;
            if (colLetter === 'Ninguna') return;

            // Verificar si está oculta o visible para alternar el estado
            const headerTest = document.querySelector('#spreadsheet-grid thead tr th:nth-child(' + (getColumnIndexFromLetter(colLetter) + 2) + ')');
            let isHidden = headerTest && headerTest.style.display === 'none';

            if (isHidden) {
                handleColumnAction('show'); // Mostrar si estaba oculta
            } else {
                handleColumnAction('hide'); // Ocultar si está visible
            }
        });
    }

    if (clearBtn) {
        // Usamos clear-column-content-btn para limpiar el contenido de la columna
        clearBtn.addEventListener('click', () => {
            handleColumnAction('clear');
        });
    }
}
